-- +goose Up
-- Tenant/Department model (docs/adr/0003). IDs and seq values are imported from the
-- legacy hospital/ward database, so both are caller-supplied (GENERATED BY DEFAULT).

CREATE TABLE tenants (
    id           varchar(100) PRIMARY KEY,
    seq          bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
    name         varchar(155) NOT NULL,
    kind         varchar(20)  NOT NULL DEFAULT 'HOSPITAL',
    legacy       boolean      NOT NULL DEFAULT false,
    hidden       boolean      NOT NULL DEFAULT false,
    address      varchar(155),
    tel          varchar(100),
    contact_name varchar(155),
    contact_tel  varchar(100),
    latitude     varchar(155),
    longitude    varchar(155),
    pic          varchar(255),
    created_at   timestamptz  NOT NULL DEFAULT now(),
    updated_at   timestamptz  NOT NULL DEFAULT now(),
    deleted_at   timestamptz,
    deleted_by   varchar(100),
    CONSTRAINT tenants_kind_check CHECK (kind IN ('HOSPITAL', 'LAB', 'FACTORY', 'CLINIC', 'PHARMACY', 'OTHER'))
);

CREATE TABLE tenant_profiles (
    tenant_id  varchar(100) PRIMARY KEY REFERENCES tenants (id) ON DELETE CASCADE,
    -- {"tenant": {"th": "...", "en": "..."}, "department": {...}}; validated by the service.
    labels     jsonb       NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT tenant_profiles_labels_object CHECK (jsonb_typeof(labels) = 'object')
);

CREATE TABLE departments (
    id         varchar(100) PRIMARY KEY,
    seq        bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
    tenant_id  varchar(100) NOT NULL REFERENCES tenants (id) ON DELETE RESTRICT,
    name       varchar(250) NOT NULL,
    legacy     boolean      NOT NULL DEFAULT false,
    created_at timestamptz  NOT NULL DEFAULT now(),
    updated_at timestamptz  NOT NULL DEFAULT now(),
    deleted_at timestamptz,
    deleted_by varchar(100)
);

-- Partial: a soft-deleted department frees its name. Restore must re-check this.
CREATE UNIQUE INDEX departments_tenant_name_key ON departments (tenant_id, name) WHERE deleted_at IS NULL;

CREATE TABLE users (
    id            varchar(100) PRIMARY KEY,
    tenant_id     varchar(100) NOT NULL REFERENCES tenants (id) ON DELETE RESTRICT,
    -- Not partial on purpose: a soft-deleted user keeps its username reserved.
    username      varchar(155) NOT NULL UNIQUE,
    password      varchar(155) NOT NULL,
    status        boolean      NOT NULL DEFAULT true,
    role          varchar(20)  NOT NULL DEFAULT 'GUEST',
    display       varchar(150),
    pic           varchar(255),
    comment       varchar(255),
    created_by    varchar(155),
    last_login_at timestamptz,
    created_at    timestamptz  NOT NULL DEFAULT now(),
    updated_at    timestamptz  NOT NULL DEFAULT now(),
    deleted_at    timestamptz,
    deleted_by    varchar(100),
    CONSTRAINT users_role_check CHECK (role IN ('SUPER', 'SERVICE', 'ADMIN', 'LEGACY_ADMIN', 'USER', 'LEGACY_USER', 'GUEST'))
);

CREATE INDEX users_tenant_id_idx ON users (tenant_id) WHERE deleted_at IS NULL;

-- A user may belong to any number of departments, or none. The service enforces that every
-- department belongs to the user's own tenant. Soft delete keeps these rows so restore brings
-- membership back; the cascade only fires on purge.
CREATE TABLE user_departments (
    user_id       varchar(100) NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    department_id varchar(100) NOT NULL REFERENCES departments (id) ON DELETE CASCADE,
    created_at    timestamptz  NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, department_id)
);

CREATE INDEX user_departments_department_id_idx ON user_departments (department_id);

-- +goose Down
DROP TABLE user_departments;
DROP TABLE users;
DROP TABLE departments;
DROP TABLE tenant_profiles;
DROP TABLE tenants;
